let last=performance.now(),clock=0,frame=0;function animate(now){requestAnimationFrame(animate);const frameDt=(now-last)/1000,dt=Math.min(frameDt,.05);last=now;clock+=dt;const lighting=cycle.update(dt,(active||!started)&&!document.hidden);const moving=(active||!started)&&!document.hidden;world.hydro.update(moving?dt:0,camera.position,lighting);world.fences.update(camera.position);world.groundDetail.update(camera.position);world.terrain.update(camera.position);world.network.update(camera.position);furniture.update(camera.position,lighting.night);world.forest.update(camera.position);world.roofDetail.update(camera.position);world.region.update(camera.position);world.coast.update(moving?dt:0,lighting,{sun:sun.position,wind:weather.state.wind});weather.update(moving?dt:0,lighting);world.weather=weather.state;if(scene.fog.far>31)scene.fog.far=Math.min(camera.far*.95,scene.fog.far*(1+Math.max(0,camera.position.y-300)/2000));world.railways.update(moving?dt:0,camera.position,lighting);radioTowers.update(camera.position,lighting.night);cellTowers.update(camera.position);if(active){$('#cross').classList.toggle('hidden',heli.active||bike.active||!!ridingMoto());if(interiors.active){$('#flight-mode').textContent=interiors.name+' · ON FOOT';$('#boundary').classList.add('hidden');}else if(driving.active){driving.update(dt);skids.update(driving.vehicle);yaw=camera.rotation.y;pitch=camera.rotation.x;$('#boundary').classList.add('hidden')}else if(heli.active){heli.update(dt);yaw=camera.rotation.y;pitch=camera.rotation.x;$('#flight-mode').textContent='HELICOPTER · '+Math.round(heli.speed*3.6)+' KM/H · ALT '+Math.round(heli.altitude)+' M · SPACE ↑ / C ↓ · G LAND';$('#boundary').classList.add('hidden')}else if(bike.active){bike.update(dt);yaw=camera.rotation.y;pitch=camera.rotation.x;$('#flight-mode').textContent='BICYCLE · '+Math.round(Math.abs(bike.speed)*3.6)+' KM/H · SHIFT PEDAL HARDER · B GET OFF';$('#boundary').classList.add('hidden')}else if(ridingMoto()){const m=ridingMoto();m.update(dt);yaw=camera.rotation.y;pitch=camera.rotation.x;$('#flight-mode').textContent=m.label+' · '+Math.round(Math.abs(m.speed)*3.6)+' KM/H · GEAR '+m.gear+(m.airborne&&m.airTime>.25?' · AIR '+m.airTime.toFixed(1)+' S':'')+' · E WHEELIE · '+(m.variant==='dirt'?'Y':'U')+' GET OFF';$('#boundary').classList.add('hidden')}else{heli.update(dt);const movement=movePlayer({position:camera.position,yaw,pitch,keys,dt,drone:aerial,world,clock});$('#boundary').classList.toggle('hidden',!movement.atBoundary);if(!aerial)$('#flight-mode').textContent=movement.mode==='diving'?'DIVING · '+movement.depth.toFixed(1)+' M · SPACE/E UP · C/Q DOWN':movement.mode==='swimming'?'SWIMMING · SPACE/E UP · C/Q DIVE':movement.mode==='wading'?'WADING':'ON FOOT';camera.rotation.set(pitch,yaw,0);}for(const q of markers){if(!q.found&&q.p.distanceTo(new T.Vector2(camera.position.x,camera.position.z))<12){q.found=true;q.m.material.color.set('#819c70');const n=markers.filter(q=>q.found).length;$('#count').textContent=`Discover ${n} / 4 places`;$('#toast').textContent=n===4?'Valley explored. Take the long way home.':`Place discovered · ${q.name}`;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,3500)}}}else if(!started){camera.rotation.set(-.05,initialYaw+Math.sin(clock*.06)*.12,0)}for(const q of markers){q.m.rotation.y=clock;q.m.position.y=ground(q.p.x,q.p.y)+3+Math.sin(clock*2)*.4}if(frame++%12===0){minimap();$('#place').textContent=interiors.active?interiors.name:busService.job.state.phase!=='idle'?'W01 · Wainui Village local':world.tunnels?.at(camera.position.x,camera.position.z,camera.position.y)?'Wainuiomata Tunnel':world.railways.underpass?.(camera.position.x,camera.position.z,camera.position.y)?.name||([...regionDestinations.values()].filter(p=>(!p.cellSite||aerial)&&Math.hypot(p.x-camera.position.x,p.z-camera.position.z)<650).sort((a,b)=>Math.hypot(a.x-camera.position.x,a.z-camera.position.z)-Math.hypot(b.x-camera.position.x,b.z-camera.position.z))[0]?.name||nearest(camera.position.x,camera.position.z).name)}traffic.update(moving?dt:0,camera.position,lighting.night);intersections.update(camera.position);people.update(moving?dt:0,camera.position);busService.update(moving?dt:0,camera.position,keys);world.water.update(moving?dt:0,camera,lighting);const car=driving.vehicle,sheltered=!!(interiors.active||world.tunnels?.at(camera.position.x,camera.position.z,camera.position.y)||world.network.underpass?.(camera.position.x,camera.position.z,camera.position.y)||world.railways.underpass?.(camera.position.x,camera.position.z,camera.position.y));rainDriving.update(dt,{active,car,firstPerson:driving.firstPerson,weather:weather.state,camera,sheltered});dashboardRadio.update({active,driving:driving.active});lookouts.update({active,onFoot:!aerial&&!driving.active&&!heli.active&&!bike.active&&!ridingMoto()&&!interiors.active,position:camera.position});parks.update(camera.position,active?dt:0,!aerial&&!driving.active&&!heli.active&&!interiors.active?camera.position:null);sound.update({active,yaw,day:lighting.day,indoors:interiors.active,position:camera.position,vehicle:driving.soundState||heli.soundState()||bike.soundState()||ridingMoto()?.soundState(),keys,weather:{...weather.state,rain:sheltered?0:weather.state.rain,wiperSwish:rainDriving.audioState.swish}});interiors.update(active?dt:0,{enabled:active&&!aerial&&!driving.active&&!heli.active&&!bike.active&&!ridingMoto(),yaw,pitch,keys});const zoom=active&&(keys.z||keys.zoom)?2.1:1;if(Math.abs(camera.zoom-zoom)>.001){camera.zoom+=(zoom-camera.zoom)*Math.min(1,dt*12);camera.updateProjectionMatrix()}sky.position.copy(camera.position);render(interiors.scene||scene,interiors.active?interiors.view:camera,interiors.active?0:lighting.night);perfHUD.update(frameDt)}animate(performance.now());

$('#mobile-drive').onclick=()=>{if(interiors.active)return;if(exitHeli());else if(driving.active)driving.exit();else{exitBike();exitMoto();aerial=false;driving.enter('car')}};$('#mobile-train').onclick=()=>{if(interiors.active)return;exitHeli();exitBike();exitMoto();aerial=false;driving.enter('train')};

